package br.com.social.comment;import br.com.social.auth.*;import br.com.social.comment.dto.*;import br.com.social.post.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/posts/{postId}/comments") public class CommentController{private final CommentRepository repo;private final PostService posts;private final AppUserRepository users;private final SimpMessagingTemplate msg;public CommentController(CommentRepository r,PostService p,AppUserRepository u,SimpMessagingTemplate m){repo=r;posts=p;users=u;msg=m;}@GetMapping public List<Comment> list(@PathVariable Long postId){posts.find(postId);return repo.findByPostIdOrderByCreatedAtAsc(postId);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Comment create(@PathVariable Long postId,@Valid @RequestBody CommentRequest q,Authentication a){posts.find(postId);AppUser u=users.findByEmail(a.getName()).orElseThrow();Comment c=repo.save(new Comment(postId,a.getName(),u.getName(),q.content()));msg.convertAndSend("/topic/social",Map.of("action","COMMENT_CREATED","postId",postId));return c;}}
